const state={config:null,user:null,csrf:null,products:[],cart:{items:[],subtotal:0},category:'Todos',search:'',adminProducts:[],adminOrders:[],quote:null,checkoutKey:null};
const $=s=>document.querySelector(s);
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const currencyLabel=()=>state.config?.currency==='EUR'?'€':'R$';
const money=v=>new Intl.NumberFormat('es-ES',{style:'currency',currency:state.config?.currency||'BRL'}).format((v||0)/100);
const date=v=>new Date(v).toLocaleString('es-ES',{dateStyle:'short',timeStyle:'short'});
const roleNames={admin:'Administrador',customer:'Cliente',inventory:'Inventario',finance:'Finanzas',shipping:'Envíos',support:'Atención al cliente'};
const ledgerTypes={income:'Cobro',refund:'Reembolso',expense:'Gasto'};
const auditActions={'invoice.issue':'Emisión de NF-e','invoice.cancel_requested':'Cancelación de NF-e solicitada','media.upload':'Foto subida','user.create':'Usuario creado','user.access':'Permisos de usuario actualizados','coupon.save':'Cupón guardado','coupon.active':'Estado del cupón actualizado','payment.duplicate':'Pago duplicado detectado','order.cancel':'Pedido cancelado','category.rename':'Categoría renombrada','category.create':'Categoría creada','product.save':'Producto guardado','stock.adjust':'Inventario ajustado','order.status':'Estado del pedido actualizado','payment.refund_requested':'Reembolso solicitado','shipping.label.create':'Etiqueta de envío creada','shipping.label.buy':'Envío comprado','shipping.label.print':'Etiqueta de envío generada','shipping.sync':'Seguimiento actualizado','finance.expense':'Gasto registrado'};
const statuses={awaiting_payment:'Pendiente de pago',paid:'Pagado',picking:'En preparación',ready:'Listo para enviar',shipped:'Enviado',delivered:'Entregado',expired:'Caducado',cancelled:'Cancelado',refunded:'Reembolsado',payment_review:'Pago en revisión',pending:'Pendiente',approved:'Aprobado'};
const badge=s=>`<span class="badge ${escape(s)}">${escape(statuses[s]||s)}</span>`;
const colors=['#f0f0f0','#e5e5e5','#fafafa','#d4d4d4','#eeeeee','#ffffff'];
const productVisual=p=>p.images?.length?`<img class="product-photo" src="${escape(p.images[0])}" alt="${escape(p.name)}" loading="lazy">`:`<span class="product-symbol" aria-hidden="true">${escape(p.icon)}</span>`;
const colorClass=c=>`color-${Math.max(1,colors.indexOf(c)+1)}`;
const has=p=>state.user?.permissions.includes(p);
const field=(name,label,value='',type='text',extra='')=>`<label class="field">${escape(label)}<input name="${name}" type="${type}" value="${escape(value)}" ${extra}></label>`;
const empty=(title,description='')=>`<div class="empty"><strong>${escape(title)}</strong>${escape(description)}</div>`;
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className=`show${error?' error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',6000);}
async function api(path,options={}) {
  const response=await fetch(`/api${path}`,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(state.csrf?{'X-CSRF-Token':state.csrf}:{}),...options.headers},...(options.body?{body:JSON.stringify(options.body)}:{})});
  const result=await response.json(); if(!response.ok) throw new Error(result.error||'No se ha podido completar la operación.');return result;
}
function dialog(title,content){const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${escape(title)}</h2><button class="icon-btn" data-action="close" aria-label="Cerrar">×</button></div><div class="dialog-body">${content}</div>`;if(!d.open)d.showModal();}
function closeDialog(){ $('#dialog').close(); }
const catalogMode=()=>state.config?.mode==='catalog';
const demoBanner=()=>catalogMode()?'<div class="demo">TIENDA EN PREPARACIÓN · Descubre los productos. Próximamente podrás comprar.</div>':state.config.mode==='demo'?'<div class="demo">ENTORNO DE DEMOSTRACIÓN · Pagos y envíos simulados, sin cargos reales.</div>':'';
const brand=()=>`<a class="brand" href="#store"><span class="brand-logo"><img src="/edg-logo.png" alt="EDG"></span></a>`;
function storeShell(content) {
  const count=state.cart.items.reduce((s,p)=>s+p.quantity,0);
  return `${demoBanner()}<header class="topbar">${brand()}<nav class="toplinks"><a href="#store">Inicio</a><a href="#catalog">Colección</a><a href="#orders">Mis pedidos</a>${has('dashboard')?'<a href="#admin">Gestión</a>':''}</nav><div class="topactions">${state.user?`<button class="btn small" data-action="account">${escape(state.user.name.split(' ')[0])} · Mi cuenta</button>`:'<button class="btn small" data-action="login">Iniciar sesión</button>'}<a class="btn small" href="#cart">Carrito <span class="cart-count">${count}</span></a></div></header><main class="store-main">${content}<footer class="footer"><span>© ${new Date().getFullYear()} EDG</span><nav aria-label="Enlaces del pie de página"><a href="#catalog">Colección</a><a href="#orders">Mis pedidos</a><a href="#cart">Carrito</a></nav><a class="footer-brand" href="#store"><img class="sr-only" src="/edg-footer-logo.png" alt="EDG" width="1122" height="125" loading="lazy" decoding="async"></a></footer></main>`;
}
function productCards(){
  const items=state.products.filter(p=>(state.category==='Todos'||p.category===state.category)&&`${p.name} ${p.sku}`.toLowerCase().includes(state.search.toLowerCase()));
  return items.length?items.map(p=>`<article class="product"><button class="product-visual ${colorClass(p.color)}" data-action="product" data-id="${p.id}" aria-label="Ver ${escape(p.name)}"><span class="chip">${p.available?'Disponible':'Agotado'}</span>${productVisual(p)}</button><div class="product-info"><span class="muted">${escape(p.category)}</span><h3>${escape(p.name)}</h3><div class="product-bottom"><span class="product-price">${money(p.price)}</span><button class="product-add" data-action="add" data-id="${p.id}" ${!p.available||catalogMode()?'disabled':''} aria-label="Añadir ${escape(p.name)}">+</button></div></div></article>`).join(''):empty('No se han encontrado productos','Cambia la búsqueda o la categoría.');
}
const deckDesigns=[['g61','Love my life'],['g99','Daniel Morán'],['63','EDG multicolor'],['121','Marcos Mama'],['197','Roger Silva'],['221','Natsuo Yashima'],['240','In Gaudí we trust'],['257','Barcelona']];
function deckCarousel(){
  const group=duplicate=>`<div class="deck-carousel-group" ${duplicate?'aria-hidden="true"':''}>${deckDesigns.map(([id,label])=>`<img src="/shape-${id}.webp" alt="${duplicate?'':escape(`Tabla EDG · ${label}`)}" width="1200" height="300" loading="lazy" decoding="async">`).join('')}</div>`;
  return `<section class="deck-carousel" aria-label="Diseños de tablas EDG"><div class="deck-carousel-window"><div class="deck-carousel-track">${group(false)}${group(true)}</div></div></section>`;
}
function storePage(){return storeShell(`<section class="campaign"><div class="campaign-copy"><span class="eyebrow">EDG / Skateboards</span><h1>TU ESTILO.<br>TUS REGLAS.</h1><p>Actitud en cada elección. Descubre la selección EDG.</p><a class="btn primary" href="#catalog">Explorar la colección ↗</a><span class="campaign-caption">IDENTIDAD PROPIA. CADA DÍA.</span></div><div class="campaign-art"><img class="campaign-photo" src="/edg-skate-campaign-1600.webp" srcset="/edg-skate-campaign-960.webp 960w, /edg-skate-campaign-1600.webp 1600w" sizes="(max-width: 760px) 100vw, 50vw" width="1600" height="1600" alt="Skater en el aire con una tabla EDG." fetchpriority="high" decoding="async"><span class="campaign-index" aria-hidden="true">EDG / 001</span><span class="campaign-art-label" aria-hidden="true">INDEPENDIENTE<br>POR NATURALEZA.</span></div></section>${deckCarousel()}<section id="catalog" class="collection-section"><div class="section-head"><div><span class="eyebrow">Descubre / La selección EDG</span><h2>LA COLECCIÓN.</h2></div><span class="collection-count">${state.products.length} productos</span></div><div class="filters">${['Todos',...new Set(state.products.map(p=>p.category))].map(c=>`<button class="filter ${state.category===c?'active':''}" data-action="filter" data-category="${escape(c)}">${escape(c)}</button>`).join('')}<label class="search"><span class="sr-only">Buscar productos</span><input id="product-search" placeholder="Buscar en la colección…" value="${escape(state.search)}"></label></div><div class="product-grid" id="product-grid">${productCards()}</div></section><section class="category-section"><div class="section-head"><h2>DESCUBRE MÁS.</h2><a href="#catalog">Ver todo ↗</a></div><div class="category-grid">${[...new Set(state.products.map(p=>p.category))].map((c,i)=>`<button class="category-tile" data-action="collection" data-category="${escape(c)}"><span class="eyebrow">EDG / 0${i+1}</span><strong>${escape(c)}</strong><span>Explorar la selección ↗</span></button>`).join('')}</div></section><section class="brand-statement"><span class="eyebrow">El universo EDG</span><h2>MÁS IDENTIDAD.<br>MENOS DE LO MISMO.</h2><a class="btn" href="#catalog">Encuentra tu próxima elección ↗</a></section>`);}
function cartPage(){if(catalogMode())return storeShell(empty('Próximamente podrás comprar','Estamos preparando la tienda. Descubre nuestro catálogo.')+'<a class="btn" href="#store">Ver productos</a>');return storeShell(`<div class="page-title"><div><span class="eyebrow">Tu selección</span><h1>Mi carrito</h1><p>Revisa tus productos y continúa con el envío.</p></div><a class="btn" href="#store">Seguir comprando</a></div>${!state.user?empty('Inicia sesión para acceder a tu carrito','Crea una cuenta o inicia sesión para empezar tu compra.')+ '<button class="btn primary" data-action="login">Acceder a mi cuenta</button>':!state.cart.items.length?empty('Tu carrito está vacío','Explora la tienda y añade tus productos favoritos.'):`<div class="cart-layout"><div class="panel">${state.cart.items.map(p=>`<div class="cart-row"><span class="cart-icon ${colorClass(p.color)}">${escape(p.icon)}</span><div><h3>${escape(p.name)}</h3><p class="muted">${money(p.price)} por unidad</p><div class="quantity"><button data-action="quantity" data-id="${p.id}" data-delta="-1" aria-label="Reducir cantidad">−</button><span>${p.quantity}</span><button data-action="quantity" data-id="${p.id}" data-delta="1" aria-label="Aumentar cantidad">+</button><button data-action="remove" data-id="${p.id}" aria-label="Eliminar producto">×</button></div></div><strong class="price">${money(p.price*p.quantity)}</strong></div>`).join('')}</div><aside class="summary"><h2>Resumen de la compra</h2><div class="sum-row"><span>Productos</span><span>${money(state.cart.subtotal)}</span></div><div class="sum-row"><span>Envío</span><span>Calculado al finalizar la compra</span></div><div class="sum-row total"><span>Subtotal</span><span>${money(state.cart.subtotal)}</span></div><button class="btn primary" data-action="checkout">Continuar con el envío →</button><p class="form-help">Las existencias se reservarán al confirmar el pedido.</p></aside></div>`}`);}
function ordersPage(orders){return storeShell(`<div class="page-title"><div><span class="eyebrow">Todo bajo control</span><h1>Mis pedidos</h1><p>Consulta el pago, la preparación y la entrega.</p></div><a class="btn" href="#store">Ir a la tienda</a></div>${!state.user?empty('Inicia sesión para ver tus pedidos')+'<button class="btn primary" data-action="login">Iniciar sesión</button>':!orders.length?empty('Todavía no tienes pedidos','Tus próximas compras aparecerán aquí.'):`<div class="order-cards">${orders.map(o=>`<article class="order-card"><div class="order-meta"><h3>Pedido #${o.number}</h3><p>${date(o.created_at)} · ${o.items.reduce((s,p)=>s+p.quantity,0)} artículo(s)</p></div>${badge(o.status)}<strong>${money(o.total)}</strong><button class="btn small" data-action="order" data-id="${o.id}">Ver pedido ↗</button></article>`).join('')}</div>`}`);}
const navItems=[['admin','Resumen','◉','dashboard'],['products','Productos','▦','catalog'],['stock','Inventario','▤','stock'],['sales','Pedidos','▣','orders'],['finance','Finanzas','↗','finance'],['shipping','Envíos','▱','shipping'],['users','Usuarios','♧','users'],['coupons','Cupones','◇','coupons'],['invoices','Facturas','▧','invoices'],['emails','Correos electrónicos','✉','users'],['audit','Actividad','◷','audit']];
function adminShell(page,content){return `${demoBanner()}<div class="admin-shell"><aside class="sidebar">${brand()}<p class="eyebrow">Gestión de la tienda</p><nav class="side-nav">${navItems.filter(n=>has(n[3])).map(([id,label,icon])=>`<a href="#${id}" class="${page===id?'active':''}"><span aria-hidden="true">${icon}</span>${label}</a>`).join('')}</nav><div class="sidebar-bottom"><a href="#store">↗ &nbsp; Acceder a la tienda</a><button class="btn small" data-action="logout">Cerrar sesión</button></div></aside><div><header class="admin-top"><p>EDG / ${escape(navItems.find(n=>n[0]===page)?.[1]||'Gestión')}</p><div class="stack"><a class="btn small" href="#store">Ver tienda ↗</a><button class="btn small" data-action="account"><span class="user-pill"><b class="avatar">${escape(state.user.name.slice(0,2).toUpperCase())}</b><span>${escape(state.user.name)}<br><small class="role-label">${roleNames[state.user.role]}</small></span></span></button></div></header><main class="admin-main">${content}</main></div></div>`;}
const title=(heading,description,action='')=>`<div class="page-title"><div><h1>${heading}</h1><p>${description}</p></div>${action}</div>`;
function orderTable(orders,shipping=false){return !orders.length?empty('Todavía no hay pedidos','Los pedidos aparecerán en esta lista.'): `<div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Fecha</th><th>Importe</th><th>${shipping?'Seguimiento':'Estado'}</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr><td><strong>#${o.number}</strong><small>${o.items.length} producto(s)</small></td><td>${escape(o.customer_name)}<small>${escape(o.customer_email)}</small></td><td>${date(o.created_at)}</td><td>${money(o.total)}</td><td>${shipping?`${escape(o.tracking_code||'Sin especificar')}<small>${statuses[o.status]}</small>`:badge(o.status)}</td><td><button class="btn small" data-action="admin-order" data-id="${o.id}">Detalles ↗</button></td></tr>`).join('')}</tbody></table></div>`;}
function dashboardPage(data){const m=data.metrics,financial=has('finance');const metrics=financial?[['Ingresos netos',money(m.net_revenue),'Cobros − reembolsos − gastos'],['Pedidos',m.orders,'Total de pedidos de la tienda'],['Pendientes de envío',m.to_ship,'Pagados, en preparación o listos'],['Existencias bajas',m.low_stock,'Productos que necesitan reposición']]:[['Pedidos',m.orders,'Total de pedidos de la tienda'],['Pendientes de envío',m.to_ship,'Próximas entregas'],['Productos',m.products,'Productos activos'],['Existencias bajas',m.low_stock,'Productos que necesitan reposición']];const max=Math.max(1,...data.revenue.map(r=>Math.abs(r.amount)));return adminShell('admin',`${title(`Hola, ${escape(state.user.name.split(' ')[0])}.`,'Una visión clara de tu tienda, del pedido a la entrega.','<button class="btn" data-action="refresh">↻ Actualizar</button>')}<div class="metrics">${metrics.map(([label,value,note])=>`<article class="metric"><div class="label">${label}<span>↗</span></div><strong>${value}</strong><p>${note}</p></article>`).join('')}</div><section class="panel"><div class="panel-title"><div><h2>Pedidos recientes</h2><p>Consulta los últimos movimientos de la tienda</p></div><a class="btn small" href="#sales">Ver todos →</a></div>${orderTable(data.recent_orders)}</section><div class="dashboard-bottom"><section class="panel"><div class="panel-title"><div><h2>${financial?'Movimientos financieros':'Tu tienda conectada'}</h2><p>${financial?'Saldo diario de los últimos días con movimientos':'Tienda, inventario y envíos en un mismo flujo'}</p></div></div>${financial&&data.revenue.length?`<div class="bar-chart" role="img" aria-label="Saldo diario: ${escape(data.revenue.slice().reverse().map(r=>`${r.day}: ${money(r.amount)}`).join('; '))}">${data.revenue.slice().reverse().map(r=>`<div class="bar h-${Math.max(1,Math.round(Math.abs(r.amount)/max*10))}" title="${r.day}: ${money(r.amount)}"></div>`).join('')}</div><p class="chart-note">La altura representa el valor absoluto. Pasa el cursor para ver los importes y sus signos.</p>`:empty('Todo listo para empezar','Las ventas confirmadas actualizarán los indicadores.')}</section><section class="panel"><div class="panel-title"><div><h2>Es hora de reponer</h2><p>Productos que requieren atención</p></div><span class="chip">${data.alerts.length}</span></div>${data.alerts.length?`<div class="alert-list">${data.alerts.slice(0,5).map(p=>`<div class="alert-item"><span>${escape(p.name)}</span><span class="badge expired">${p.available} un.</span></div>`).join('')}</div>`:empty('Inventario al día','No hay avisos de reposición.')}</section></div>`);}
function productsPage(products,stock=false){return adminShell(stock?'stock':'products',`${title(stock?'Inventario':'Productos',stock?'Existencias físicas, reservas y movimientos trazables.':'Organiza el catálogo y los precios de tu tienda.',stock?'':'<button class="btn primary" data-action="categories">Categorías</button><button class="btn primary" data-action="new-product">+ Nuevo producto</button>')}${stock?'<div class="note">Disponible = existencias físicas − reservas. Los ajustes requieren un motivo y no pueden consumir unidades reservadas.</div>':''}<section class="panel"><div class="table-wrap"><table><thead><tr><th>Producto / SKU</th>${stock?'<th>Físico</th><th>Reservado</th><th>Disponible</th>':'<th>Categoría</th><th>Precio</th><th>Estado</th>'}<th></th></tr></thead><tbody>${products.map(p=>`<tr><td><strong>${escape(p.icon)} &nbsp; ${escape(p.name)}</strong><small>${escape(p.sku)}${p.size?` · ${escape(p.size)}`:''}</small></td>${stock?`<td>${p.stock}</td><td>${p.reserved}</td><td>${p.available<=p.low_stock?`<span class="badge expired">${p.available} · Reponer</span>`:p.available}</td>`:`<td>${escape(p.category)}</td><td>${money(p.price)}<small>Coste ${money(p.cost)}</small></td><td>${p.active?'<span class="badge approved">Activo</span>':'<span class="badge cancelled">Inactivo</span>'}</td>`}<td><button class="btn small" data-action="${stock?'adjust-stock':'edit-product'}" data-id="${p.id}">${stock?'Ajustar inventario':'Editar'}</button></td></tr>`).join('')}</tbody></table></div>${!products.length?empty('Añade tu primer producto'):''}</section>${stock?'<section class="panel"><div class="panel-title"><h2>Últimos movimientos</h2></div><div id="movements"></div></section>':''}`);}
function financePage(ledger,data){const income=ledger.filter(l=>l.type==='income').reduce((s,l)=>s+l.amount,0),refunds=ledger.filter(l=>l.type==='refund').reduce((s,l)=>s+l.amount,0),expenses=ledger.filter(l=>l.type==='expense').reduce((s,l)=>s+l.amount,0);return adminShell('finance',`${title('Finanzas','Cobros confirmados, gastos y reembolsos.','<button class="btn primary" data-action="expense">+ Registrar gasto</button>')}<div class="metrics">${[['Saldo neto',money(data.metrics.net_revenue),'Total de todo el historial'],['Cobros',money(income),'Últimos 500 movimientos'],['Reembolsos',money(-refunds),'Últimos 500 movimientos'],['Gastos',money(-expenses),'Últimos 500 movimientos']].map(([a,b,c])=>`<article class="metric"><div class="label">${a}</div><strong>${b}</strong><p>${c}</p></article>`).join('')}</div><div class="note">Los ingresos netos son el saldo de los cobros, reembolsos y gastos registrados. Las comisiones de la pasarela y los costes de envío deben registrarse como gastos. Este panel no calcula el beneficio contable.</div><section class="panel"><div class="panel-title"><h2>Movimientos</h2><button class="btn small" data-action="export-finance">Exportar CSV ↓</button></div>${ledger.length?`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Descripción</th><th>Tipo</th><th>Importe</th></tr></thead><tbody>${ledger.map(l=>`<tr><td>${date(l.created_at)}</td><td>${escape(l.description)}</td><td>${escape(ledgerTypes[l.type]||l.type)}</td><td class="${l.amount>0?'ledger-positive':'ledger-negative'}"><strong>${money(l.amount)}</strong></td></tr>`).join('')}</tbody></table></div>`:empty('Todavía no hay movimientos')}</section>`);}
function usersPage(users){return adminShell('users',`${title('Usuarios y accesos','Cada persona tiene los permisos necesarios para su función.','<button class="btn primary" data-action="new-user">+ Nuevo usuario</button>')}<section class="panel"><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Correo electrónico</th><th>Perfil</th><th>Estado</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td><strong>${escape(u.name)}</strong></td><td>${escape(u.email)}</td><td>${roleNames[u.role]}</td><td>${u.active?'<span class="badge approved">Activo</span>':'<span class="badge cancelled">Bloqueado</span>'}</td><td>${u.id!==state.user.id?`<button class="btn small" data-action="edit-user" data-id="${u.id}">Permisos</button>`:'<span class="muted">Tu acceso</span>'}</td></tr>`).join('')}</tbody></table></div></section>`);}
let renderVersion=0;
async function render(){const version=++renderVersion;let page=location.hash.slice(1)||'store';if(page==='catalog')page='store';const needsLogin=!state.user&&navItems.some(([id])=>id===page);if(needsLogin)page='store';try{
  let html;
  if(page.startsWith('reset-password/')){html=storeShell('<div class="password-page"><h1>Crea una nueva contraseña</h1><p class="muted">El enlace es temporal y solo se puede utilizar una vez.</p><form id="reset-form" data-token="'+escape(page.split('/')[1])+'">'+field('password','Nueva contraseña','','password','required minlength="12" maxlength="128" autocomplete="new-password"')+'<button class="btn primary" type="submit">Guardar nueva contraseña</button></form></div>');}
  else if(['store','cart','orders'].includes(page)) {
    state.products=await api('/products');if(state.user)state.cart=await api('/cart');
    html=page==='store'?storePage():page==='cart'?cartPage():ordersPage(state.user?await api('/orders'):[]);
  } else {
    if(!has('dashboard')) {location.hash='store';if(!state.user)authDialog();return;}
    const permission=navItems.find(n=>n[0]===page)?.[3];if(!permission || !has(permission)){location.hash='admin';return;}
    if(page==='admin')html=dashboardPage(await api('/admin/dashboard'));
    if(['products','stock'].includes(page)){state.adminProducts=await api('/admin/products');if(page==='products')state.categories=await api('/admin/categories');html=productsPage(state.adminProducts,page==='stock');}
    if(['sales','shipping'].includes(page)){state.adminOrders=await api('/admin/orders');let orders=state.adminOrders;if(page==='shipping')orders=orders.filter(o=>['paid','picking','ready','shipped','delivered'].includes(o.status));html=adminShell(page,`${title(page==='shipping'?'Envíos y entregas':'Pedidos',page==='shipping'?'Prepara, envía y consulta cada entrega.':'Un historial para cada venta.','<button class="btn" data-action="refresh">↻ Actualizar</button>')}<div class="filters">${['Todos',...(page==='shipping'?['paid','picking','ready','shipped','delivered']:['awaiting_payment','paid','shipped','cancelled','payment_review'])].map(s=>`<button class="filter ${s==='Todos'?'active':''}" data-action="order-filter" data-status="${s}" data-shipping="${page==='shipping'}">${statuses[s]||s}</button>`).join('')}</div><section class="panel" id="orders-table">${orderTable(orders,page==='shipping')}</section>`);}
    if(page==='finance'){state.ledger=await api('/admin/finance');html=financePage(state.ledger,await api('/admin/dashboard'));}
    if(page==='coupons'){state.coupons=await api('/admin/coupons');html=couponsPage(state.coupons);}
    if(page==='invoices'){state.invoices=await api('/admin/invoices');html=invoicesPage(state.invoices);}
    if(page==='emails'){html=emailsPage(await api('/admin/emails'));}
    if(page==='users'){state.users=await api('/admin/users');html=usersPage(state.users);}
    if(page==='audit'){const logs=await api('/admin/audit');html=adminShell(page,`${title('Actividad','Historial de los cambios realizados por el equipo.')}<section class="panel"><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Acción</th><th>Referencia</th></tr></thead><tbody>${logs.map(l=>`<tr><td>${date(l.created_at)}</td><td>${escape(l.actor_name||'Sistema')}</td><td>${escape(auditActions[l.action]||l.action)}</td><td>${escape(l.entity_id||'—')}</td></tr>`).join('')}</tbody></table></div></section>`);}
  }
  if(version!==renderVersion)return;$('#app').innerHTML=html;if(needsLogin)authDialog();
  if(page==='stock'){const rows=await api('/admin/movements');if(version!==renderVersion)return;$('#movements').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Producto</th><th>Variación</th><th>Motivo</th><th>Responsable</th><th>Fecha</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escape(r.product_name)}</td><td>${r.quantity>0?'+':''}${r.quantity}</td><td>${escape(r.reason)}</td><td>${escape(r.actor_name||'Sistema')}</td><td>${date(r.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No hay movimientos');}
  if(location.hash==='#catalog')$('#catalog')?.scrollIntoView({behavior:'smooth'});
}catch(e){toast(e.message,true);if(!$('#app').children.length)$('#app').innerHTML=empty('No se ha podido cargar','Actualiza la página para volver a intentarlo.');}}
function authDialog(register=false){dialog(register?'Crea tu cuenta':'Te damos la bienvenida',`<p class="muted">${register?'Regístrate para comprar y consultar tus pedidos.':'Inicia sesión para acceder a tu tienda y tus pedidos.'}</p><form id="auth-form" data-register="${register}">${register?field('name','Nombre completo','','text','required minlength="2" autocomplete="name"'):''}${field('email','Correo electrónico','','email','required autocomplete="email"')}${field('password','Contraseña','','password',`required ${register?'minlength="12"':''} maxlength="128" autocomplete="${register?'new-password':'current-password'}"`)}${register?'<p class="form-help">Utiliza una contraseña exclusiva de al menos 12 caracteres.</p>':''}<div class="form-actions"><button class="btn primary" type="submit">${register?'Crear cuenta':'Iniciar sesión'}</button></div></form>${!register?'<div class="switch-auth"><button data-action="forgot">He olvidado mi contraseña</button></div>':''}<div class="switch-auth">${register?'¿Ya tienes cuenta?':'¿Todavía no tienes cuenta?'}<button data-action="${register?'login':'register'}">${register?'Iniciar sesión':'Crear mi cuenta'}</button></div>`);}
function accountDialog(){dialog('Mi cuenta',`<h3>${escape(state.user.name)}</h3><p class="muted">${escape(state.user.email)} · ${roleNames[state.user.role]}</p><div class="stack form-actions">${has('dashboard')?'<a class="btn" href="#admin" data-action="close">Acceder a la gestión</a>':''}<button class="btn" data-action="password">Cambiar contraseña</button><button class="btn danger" data-action="logout">Cerrar sesión</button></div>`);}
function checkoutDialog(){if(catalogMode())return toast('Próximamente podrás comprar.');state.quote=null;state.coupon=null;state.checkoutKey=crypto.randomUUID();dialog('Envío y pago',`<form id="checkout-form"><div class="form-grid">${field('name','Nombre del destinatario',state.user.name,'text','required')}${field('phone','Teléfono','','tel','required')}${field('document','CPF / CNPJ','','text','required')}${field('postal_code','Código postal (CEP)','','text','required maxlength="9"')}${field('street','Calle / Avenida','','text','required')}${field('number','Número','','text','required')}${field('district','Barrio','','text','required')}${field('complement','Información adicional')}${field('city','Ciudad','','text','required')}${field('state','Estado (UF)','','text','required minlength="2" maxlength="2" pattern="[A-Z]{2}"')}</div><div class="coupon-entry">${field('coupon','Cupón de descuento (opcional)')}<button class="btn" type="button" data-action="apply-coupon">Aplicar cupón</button></div><div id="coupon-summary"></div><button type="button" class="btn form-actions" data-action="quote">Calcular envío</button><div id="quote-results" class="quote-results"></div><div class="checkout-total"><span>Productos</span><span id="checkout-products-total">${money(state.cart.subtotal)}</span></div><p class="form-help">${state.config.mode==='demo'?'Demostración: podrás simular el pago en el pedido.':'Se te redirigirá a Mercado Pago para elegir el método de pago.'}</p><div class="form-actions"><button class="btn primary" type="submit" id="place-order" disabled>Confirmar pedido →</button></div></form>`);}
function productDialog(p){dialog(p.name,`<div class="product-visual ${colorClass(p.color)}">${productVisual(p)}</div>${p.images?.length>1?`<div class="photo-gallery">${p.images.map(url=>`<button data-action="photo-main" data-url="${escape(url)}"><img src="${escape(url)}" alt="Foto de ${escape(p.name)}"></button>`).join('')}</div>`:''}<p class="muted form-help">${escape(p.category)}${p.size?` · Talla: ${escape(p.size)}`:''} · ${escape(p.sku)}</p><p>${escape(p.description)}</p><div class="detail-heading form-actions"><strong>${money(p.price)}</strong><button class="btn primary" data-action="add" data-id="${p.id}" ${!p.available||catalogMode()?'disabled':''}>${catalogMode()?'Disponible próximamente':p.available?'Añadir al carrito':'Agotado'}</button></div>`);}
function categoriesDialog(){dialog('Categorías',`<form id="category-form">${field('name','Nueva categoría','','text','required maxlength="80"')}<div class="form-actions"><button class="btn primary">Añadir categoría</button></div></form><p class="form-help">Al cambiar el nombre de una categoría se actualizan todos los productos asociados.</p>${state.categories.map(c=>`<form class="category-edit-form" data-previous="${escape(c.name)}"><div class="form-grid">${field('name','Categoría',c.name,'text','required maxlength="80"')}<div class="form-actions"><button class="btn">Guardar cambios</button></div></div></form>`).join('')}`);}
function sizeField(category,value=''){
  const sizes=state.categories.find(c=>c.name===category)?.sizes||[];
  return sizes.length?`<label class="field">${/shai?pe|tabla/i.test(category)?'Anchura de la tabla (pulgadas)':'Talla'}<select name="size" required><option value="">Selecciona la talla</option>${sizes.map(size=>`<option value="${escape(size)}" ${value===size?'selected':''}>${escape(size)}</option>`).join('')}</select></label><p class="form-help">Crea un SKU por talla para controlar las existencias.</p>`:field('size','Talla (opcional)',value,'text','maxlength="30"');
}
function productEditor(p={}){state.editPhotoIds=JSON.parse(p.images||'[]');state.uploading=false;dialog(p.id?'Editar producto':'Nuevo producto',`<form id="product-form" data-id="${p.id||''}"><div class="form-grid">${field('name','Nombre',p.name||'','text','required')}${field('sku','SKU',p.sku||'','text','required')}<label class="field">Categoría<select name="category" required><option value="">Selecciona una categoría</option>${state.categories.map(c=>`<option value="${escape(c.name)}" ${p.category===c.name?'selected':''}>${escape(c.name)}</option>`).join('')}</select></label><div id="product-size">${sizeField(p.category||'',p.size||'')}</div>${field('price',`Precio (${currencyLabel()})`,((p.price||0)/100).toFixed(2),'number','required min="0.01" step="0.01"')}${field('cost',`Coste (${currencyLabel()})`,((p.cost||0)/100).toFixed(2),'number','required min="0" step="0.01"')}${field('low_stock','Aviso de existencias',p.low_stock??5,'number','required min="0"')}${field('weight','Peso (kg)',p.weight||0.5,'number','required min="0.001" step="0.001"')}${field('width','Anchura (cm)',p.width||20,'number','required min="1" step="0.1"')}${field('height','Altura (cm)',p.height||10,'number','required min="1" step="0.1"')}${field('length','Longitud (cm)',p.length||25,'number','required min="1" step="0.1"')}${field('icon','Símbolo del producto',p.icon||'◇','text','required maxlength="8"')}<label class="field">Color<select name="color">${colors.map((c,i)=>`<option value="${c}" ${p.color===c?'selected':''}>Paleta ${i+1}</option>`).join('')}</select></label><div class="field full"><span>Fotos del producto</span><input id="product-photos" type="file" accept="image/jpeg,image/png,image/webp" multiple><p class="form-help">Hasta 8 fotos, con un máximo de 5 MB cada una. JPEG, PNG o WebP.</p><div id="photo-preview" class="photo-gallery">${photoPreview()}</div></div>${state.config.currency==='EUR'?'':fiscalEditor(JSON.parse(p.fiscal||'{}'))}<label class="field full">Descripción<textarea name="description" required maxlength="2000">${escape(p.description||'')}</textarea></label><label class="field">Estado<select name="active"><option value="true" ${p.active!==0?'selected':''}>Activo</option><option value="false" ${p.active===0?'selected':''}>Inactivo</option></select></label></div><p class="form-help">Las existencias iniciales y las reposiciones se registran en la sección Inventario.</p><div class="form-actions"><button class="btn primary" type="submit">Guardar producto</button></div></form>`);}
function stockDialog(p){dialog(`Ajustar inventario · ${p.name}`,`<p class="muted">Físico: ${p.stock} · Reservado: ${p.reserved} · Disponible: ${p.available}</p><form id="stock-form" data-id="${p.id}">${field('delta','Variación en unidades (p. ej., 10 o −2)','','number','required step="1"')}${field('reason','Motivo del ajuste','','text','required minlength="3"')}<p class="form-help">Utiliza un valor positivo para las entradas y negativo para las salidas. Comprueba y registra aquí las devoluciones posteriores a la entrega.</p><div class="form-actions"><button class="btn primary" type="submit">Registrar ajuste</button></div></form>`);}
function userDialog(u=null){dialog(u?'Cambiar permisos':'Nuevo usuario',`<form id="user-form" data-id="${u?.id||''}">${!u?field('name','Nombre','','text','required')+field('email','Correo electrónico','','email','required')+field('password','Contraseña inicial','','password','required minlength="12" maxlength="128"'): `<h3>${escape(u.name)}</h3><p class="muted">${escape(u.email)}</p>`}<label class="field">Perfil<select name="role">${Object.entries(roleNames).map(([role,label])=>`<option value="${role}" ${u?.role===role?'selected':''}>${label}</option>`).join('')}</select></label>${u?`<label class="field">Estado<select name="active"><option value="true" ${u.active?'selected':''}>Activo</option><option value="false" ${!u.active?'selected':''}>Bloqueado</option></select></label>`:'<p class="form-help">El usuario podrá cambiar la contraseña en Mi cuenta.</p>'}<div class="form-actions"><button class="btn primary" type="submit">Guardar usuario</button></div></form>`);}
function orderDialog(o,admin=false){state.currentOrder={order:o,admin};const a=o.address;const next={paid:['picking','Iniciar preparación'],picking:['ready','Marcar como empaquetado'],ready:['shipped','Registrar envío'],shipped:['delivered','Confirmar entrega']}[o.status];dialog(`Pedido #${o.number}`,`<div class="detail-heading">${badge(o.status)}<strong>${money(o.total)}</strong></div><p>${escape(o.customer_name)} · ${escape(o.customer_email)}</p><p class="muted">${escape(a.street)}, ${escape(a.number)} ${escape(a.complement)} · ${escape(a.district)}<br>${escape(a.city)} / ${escape(a.state)} · Código postal ${escape(a.postal_code)}</p><div class="detail-items">${o.items.map(p=>`<div><span>${p.quantity}× ${escape(p.name)}</span><strong>${money(p.price*p.quantity)}</strong></div>`).join('')}${o.discount?`<div><span>Cupón ${escape(o.coupon_code)}</span><strong>− ${money(o.discount)}</strong></div>`:''}<div><span>Envío · ${escape(o.shipping_service.name)}</span><strong>${money(o.shipping)}</strong></div></div>${o.tracking_code?`<p><b>Seguimiento:</b> ${escape(o.tracking_code)} ${o.tracking_url?`<a class="btn small" href="${escape(o.tracking_url)}" target="_blank" rel="noopener noreferrer">Seguir envío ↗</a>`:''}</p>`:''}${o.status==='awaiting_payment'?`<p class="form-help">Reserva válida hasta ${date(o.reserved_until)}.</p>`:''}${o.refunded?`<p class="danger-note">Reembolsado: ${money(o.refunded)}</p>`:''}${invoiceSummary(o.invoice)}<div class="timeline">${o.events.map(e=>`<div><p>${escape(e.message)}</p><small>${date(e.created_at)}</small></div>`).join('')}</div><div class="detail-actions">${admin&&has('invoices')?`<button class="btn" data-action="invoice" data-id="${o.id}">${o.invoice?'Gestionar NF-e':'Emitir NF-e'}</button>`:''}${!admin&&o.status==='awaiting_payment'?`<button class="btn primary" data-action="${state.config.mode==='demo'?'demo-pay':'pay'}" data-id="${o.id}">${state.config.mode==='demo'?'Simular pago aprobado':'Pagar con Mercado Pago ↗'}</button><button class="btn danger" data-action="cancel-order" data-id="${o.id}">Cancelar pedido</button>`:''}${admin&&has('shipping')&&next&&o.refunded===0?`<button class="btn primary" data-action="next-status" data-id="${o.id}" data-status="${next[0]}">${next[1]}</button>`:''}${admin&&has('finance')&&o.payment_status==='approved'?`<button class="btn danger" data-action="refund" data-id="${o.id}">Reembolsar pago</button>`:''}${admin&&has('shipping')&&o.status==='awaiting_payment'?`<button class="btn danger" data-action="admin-cancel" data-id="${o.id}">Cancelar pedido</button>`:''}${admin&&has('shipping')&&state.config.mode==='live'&&['paid','picking','ready'].includes(o.status)&&!o.refunded?`<button class="btn" data-action="label" data-id="${o.id}">${o.label_id?'Gestionar etiqueta':'Crear etiqueta'}</button>`:''}${admin&&has('shipping')&&o.label_id?`<button class="btn" data-action="tracking-sync" data-id="${o.id}">Consultar transportista</button>`:''}${admin&&o.label_url?`<a class="btn" href="${escape(o.label_url)}" target="_blank" rel="noopener noreferrer">Imprimir etiqueta ↗</a>`:''}</div>`);}
async function afterOrderAction(o,admin){orderDialog(o,admin);await render();}
document.addEventListener('input',e=>{if(e.target.id==='product-search'){state.search=e.target.value;$('#product-grid').innerHTML=productCards();}if(e.target.form?.id==='checkout-form'&&e.target.name==='coupon'){state.coupon=null;$('#coupon-summary').textContent='';$('#checkout-products-total').textContent=money(state.cart.subtotal);}
if(e.target.form?.id==='checkout-form'&&e.target.name==='postal_code'){state.quote=null;$('#quote-results').innerHTML='';$('#place-order').disabled=true;}});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;el.disabled=true;try{
  if(action==='close')closeDialog();
  if(action==='forgot')forgotDialog();
  if(action==='photo-main'){$('#dialog .product-photo').src=el.dataset.url;}
  if(action==='remove-photo'){state.editPhotoIds.splice(Number(el.dataset.index),1);$('#photo-preview').innerHTML=photoPreview();}
  if(action==='new-coupon')couponDialog();
  if(action==='toggle-coupon'){await api(`/admin/coupons/${el.dataset.code}`,{method:'PATCH',body:{active:el.dataset.active==='true'}});await render();}
  if(action==='apply-coupon'){const code=$('#checkout-form').elements.coupon.value.trim();state.coupon=code?await api('/coupons/check',{method:'POST',body:{code}}):null;$('#coupon-summary').textContent=state.coupon?`Descuento: ${money(state.coupon.discount)} · ${state.coupon.code}`:'';$('#checkout-products-total').textContent=money(state.cart.subtotal-(state.coupon?.discount||0));}
  if(action==='invoice'){const order=state.adminOrders.find(o=>o.id===id)||await api('/admin/orders').then(rows=>rows.find(o=>o.id===id));const rows=await api('/admin/invoices');const row=rows.find(i=>i.order_id===id);invoiceDialog(order,row);}
  if(action==='invoice-issue'){state.invoiceOrderId=id;const preview=await api(`/admin/orders/${id}/invoice-preview`);invoiceIssueDialog(id,preview);}
  if(action==='invoice-consult'){const row=await api(`/admin/orders/${id}/invoice`,{method:'POST',body:{action:'consult'}});invoiceDialog(state.invoiceOrder,row);await render();}
  if(action==='invoice-cancel')dialog('Cancelar NF-e',`<p>Se solicitará la cancelación al proveedor fiscal. El reembolso del pago es una operación independiente.</p><form id="invoice-cancel-form" data-id="${id}">${field('reason','Justificación','','text','required minlength="15" maxlength="255"')}<div class="form-actions"><button class="btn danger" type="submit">Confirmar cancelación fiscal</button></div></form>`);
  if(action==='login')authDialog();if(action==='register')authDialog(true);if(action==='account')accountDialog();
  if(action==='collection'){state.category=el.dataset.category;location.hash='catalog';await render();document.querySelector('#catalog')?.scrollIntoView();return;}
  if(action==='logout'){await api('/auth/logout',{method:'POST'});state.user=null;state.csrf=null;state.cart={items:[],subtotal:0};closeDialog();location.hash='store';await render();}
  if(action==='password')dialog('Cambiar contraseña',`<form id="password-form">${field('current_password','Contraseña actual','','password','required autocomplete="current-password"')}${field('password','Nueva contraseña','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<p class="form-help">Tendrás que volver a iniciar sesión después de guardar.</p><div class="form-actions"><button class="btn primary">Guardar contraseña</button></div></form>`);
  if(action==='categories')categoriesDialog();
  if(action==='filter'){state.category=el.dataset.category;await render();}
  if(action==='product')productDialog(state.products.find(p=>p.id===id));
  if(action==='add'){if(!state.user){authDialog();return;}const p=state.cart.items.find(p=>p.id===id);state.cart=await api(`/cart/${id}`,{method:'PUT',body:{quantity:(p?.quantity||0)+1}});toast('Producto añadido al carrito.');closeDialog();await render();}
  if(['quantity','remove'].includes(action)){const p=state.cart.items.find(p=>p.id===id);state.cart=await api(`/cart/${id}`,{method:'PUT',body:{quantity:action==='remove'?0:p.quantity+Number(el.dataset.delta)}});await render();}
  if(action==='checkout')checkoutDialog();
  if(action==='quote'){const form=$('#checkout-form');const cep=form.elements.postal_code.value;state.quote=await api('/shipping/quote',{method:'POST',body:{postal_code:cep}});$('#quote-results').innerHTML=state.quote.options.map((q,i)=>`<label class="shipping-choice"><input type="radio" name="service_id" value="${escape(q.id)}" ${i===0?'checked':''}><span>${escape(q.name)}<br><small class="muted">Estimación de ${escape(q.days)} días laborables</small></span><strong>${money(q.price)}</strong></label>`).join('');$('#place-order').disabled=false;}
  if(action==='order')orderDialog(await api(`/orders/${id}`));
  if(action==='admin-order')orderDialog(state.adminOrders.find(o=>o.id===id)||await api('/admin/orders').then(rows=>rows.find(o=>o.id===id)),true);
  if(action==='demo-pay')await afterOrderAction(await api(`/orders/${id}/demo-pay`,{method:'POST'}),false);
  if(action==='pay'){const o=await api(`/orders/${id}/payment`,{method:'POST'});if(o.payment_url)location.assign(o.payment_url);}
  if(action==='cancel-order'){const o=await api(`/orders/${id}/cancel`,{method:'POST'});await afterOrderAction(o,false);}
  if(action==='admin-cancel')await afterOrderAction(await api(`/admin/orders/${id}/cancel`,{method:'POST'}),true);
  if(action==='next-status'){if(el.dataset.status==='shipped')dialog('Registrar envío',`<form id="shipping-form" data-id="${id}">${field('tracking_code','Código de seguimiento','','text','required minlength="3"')}${field('tracking_url','Enlace de seguimiento (opcional)','','url')}<div class="form-actions"><button class="btn primary">Confirmar envío</button></div></form>`);else await afterOrderAction(await api(`/admin/orders/${id}/status`,{method:'POST',body:{status:el.dataset.status}}),true);}
  if(action==='refund')dialog('Reembolsar pago',`<p>¿Confirmas el reembolso íntegro de este pedido? ${state.config.mode==='live'?'Esta acción solicita un reembolso real a Mercado Pago.':'Este reembolso será simulado.'}</p><p class="form-help">Las existencias solo se reponen automáticamente antes del envío. Si la mercancía ya se ha enviado, comprueba la devolución y registra la entrada en Inventario.</p><form id="refund-form" data-id="${id}"><div class="form-actions"><button type="button" class="btn" data-action="close">Volver</button><button class="btn danger">Confirmar reembolso íntegro</button></div></form>`);
  if(action==='label'){const o=state.currentOrder.order;dialog('Etiqueta de envío',o.label_id?`<p>Etiqueta: ${escape(o.label_id)}</p><p class="form-help">La compra del envío utiliza el saldo de la cuenta de Melhor Envio. Si se produce un error o la respuesta es incierta, consulta el panel antes de repetir la operación.</p><div class="form-actions"><button class="btn" data-action="label-buy-confirm" data-id="${id}">Comprar envío</button><button class="btn primary" data-action="label-print" data-id="${id}">Generar e imprimir</button></div>`:`<form id="label-form" data-id="${id}">${field('invoice_key','Clave de la NF-e (44 dígitos)','','text','required pattern="[0-9]{44}" maxlength="44"')}<p class="form-help">La NF-e debe emitirse en tu sistema fiscal. Este sistema no emite facturas.</p><div class="form-actions"><button class="btn primary">Crear etiqueta en Melhor Envio</button></div></form>`);}
  if(action==='label-buy-confirm')dialog('Confirmar compra del envío',`<p>Esta acción utiliza el saldo de tu cuenta de Melhor Envio para comprar el envío.</p><form id="label-buy-form" data-id="${id}"><div class="form-actions"><button class="btn primary">Confirmar compra</button></div></form>`);
  if(action==='label-print')await afterOrderAction(await api(`/admin/orders/${id}/label`,{method:'POST',body:{action:'print'}}),true);
  if(action==='tracking-sync'){const result=await api(`/admin/orders/${id}/tracking`,{method:'POST'});await afterOrderAction(result.order,true);toast(result.tracking.label);}
  if(action==='new-product')productEditor();if(action==='edit-product')productEditor(state.adminProducts.find(p=>p.id===id));if(action==='adjust-stock')stockDialog(state.adminProducts.find(p=>p.id===id));
  if(action==='new-user')userDialog();if(action==='edit-user')userDialog(state.users.find(u=>u.id===id));
  if(action==='expense'){state.expenseKey=crypto.randomUUID();dialog('Registrar gasto',`<form id="expense-form">${field('description','Descripción','','text','required minlength="3"')}${field('amount',`Importe (${currencyLabel()})`,'','number','required min="0.01" step="0.01"')}<div class="form-actions"><button class="btn primary">Registrar gasto</button></div></form>`);}
  if(action==='export-finance'){const cell=v=>`"${String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'")}"`;const csv=`\uFEFFFecha;Descripción;Tipo;Importe (${currencyLabel()})\n`+state.ledger.map(r=>[r.created_at,r.description,ledgerTypes[r.type]||r.type,(r.amount/100).toFixed(2)].map(cell).join(';')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const link=document.createElement('a');link.href=url;link.download='edg-finanzas.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  if(action==='order-filter'){document.querySelectorAll('.filter').forEach(f=>f.classList.remove('active'));el.classList.add('active');const shipping=el.dataset.shipping==='true',s=el.dataset.status;const rows=state.adminOrders.filter(o=>(s==='Todos'||o.status===s)&&(!shipping||['paid','picking','ready','shipped','delivered'].includes(o.status)));$('#orders-table').innerHTML=orderTable(rows,shipping);}
  if(action==='refresh')await render();
}catch(error){toast(error.message,true);}finally{el.disabled=false;}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,btn=form.querySelector('[type="submit"]')||form.querySelector('button:last-child');if(btn)btn.disabled=true;const data=Object.fromEntries(new FormData(form));try{
  if(form.id==='forgot-form'){const r=await api('/auth/forgot-password',{method:'POST',body:{email:data.email}});dialog('Consulta tu correo electrónico',`<p>${escape(r.message)}</p>${state.config.mode==='demo'?'<p class="form-help">En la demostración, el administrador puede consultar el mensaje en el panel de Correos electrónicos.</p>':''}`);}
  if(form.id==='reset-form'){await api('/auth/reset-password',{method:'POST',body:{token:form.dataset.token,password:data.password}});state.user=null;state.csrf=null;state.cart={items:[],subtotal:0};location.hash='store';await render();authDialog();toast('Contraseña actualizada. Vuelve a iniciar sesión.');}
  if(form.id==='coupon-form'){const p={...data,value:data.type==='percent'?Math.round(Number(data.value)*100):Math.round(Number(data.value)*100),min_subtotal:Math.round(Number(data.min_subtotal)*100),max_discount:data.max_discount?Math.round(Number(data.max_discount)*100):null,max_uses:Number(data.max_uses),per_user_limit:Number(data.per_user_limit),starts_at:new Date(data.starts_at).toISOString(),ends_at:new Date(data.ends_at).toISOString(),active:true};await api('/admin/coupons',{method:'POST',body:p});closeDialog();await render();toast('Cupón creado.');}
  if(form.id==='invoice-emit-form'){const row=await api(`/admin/orders/${form.dataset.id}/invoice`,{method:'POST',body:{action:'emit',fiscal:{items:Array.from({length:Number(data.item_count)},(_,i)=>readFiscal(data,`item_${i}_`)),payment:{...JSON.parse(data.payment_extra||'{}'),forma_pagamento:data.payment_type}}}});invoiceDialog(state.invoiceOrder,row);await render();}
  if(form.id==='invoice-cancel-form'){const row=await api(`/admin/orders/${form.dataset.id}/invoice`,{method:'POST',body:{action:'cancel',reason:data.reason}});invoiceDialog(state.invoiceOrder,row);await render();}
  if(form.id==='auth-form'){const register=form.dataset.register==='true',result=await api(`/auth/${register?'register':'login'}`,{method:'POST',body:data});state.user=result.user;state.csrf=result.csrf;closeDialog();location.hash=has('dashboard')?'admin':'store';await render();toast(register?'Tu cuenta se ha creado.':'Has iniciado sesión.');}
  if(form.id==='checkout-form'){if(!state.quote)throw new Error('Calcula el envío antes de confirmar.');const {service_id,coupon,...address}=data;const o=await api('/checkout',{method:'POST',headers:{'Idempotency-Key':state.checkoutKey},body:{quote_id:state.quote.id,service_id,address,coupon:coupon||null}});location.hash='orders';await render();orderDialog(o);if(state.config.mode==='live'&&o.payment_url)location.assign(o.payment_url);}
  if(form.id==='category-form'||form.classList.contains('category-edit-form')){await api('/admin/categories',{method:'POST',body:{name:data.name,...(form.dataset.previous?{previous:form.dataset.previous}:{})}});await render();categoriesDialog();toast('Categoría guardada.');}
  if(form.id==='product-form'){if(state.uploading)throw new Error('Espera a que se suban las fotos.');const p={...data,images:state.editPhotoIds,fiscal:readFiscal(data),price:Math.round(Number(data.price)*100),cost:Math.round(Number(data.cost)*100),active:data.active==='true'};for(const k of ['low_stock','weight','width','height','length'])p[k]=Number(data[k]);await api(`/admin/products${form.dataset.id?'/'+form.dataset.id:''}`,{method:form.dataset.id?'PUT':'POST',body:p});closeDialog();await render();toast('Producto guardado.');}
  if(form.id==='stock-form'){await api(`/admin/products/${form.dataset.id}/stock`,{method:'POST',body:{delta:Number(data.delta),reason:data.reason}});closeDialog();await render();toast('Inventario actualizado.');}
  if(form.id==='user-form'){await api(`/admin/users${form.dataset.id?'/'+form.dataset.id:''}`,{method:form.dataset.id?'PATCH':'POST',body:{...data,active:data.active==='true'}});closeDialog();await render();toast('Acceso actualizado.');}
  if(form.id==='expense-form'){await api('/admin/expenses',{method:'POST',headers:{'Idempotency-Key':state.expenseKey},body:{description:data.description,amount:Math.round(Number(data.amount)*100)}});closeDialog();await render();toast('Gasto registrado.');}
  if(form.id==='shipping-form')await afterOrderAction(await api(`/admin/orders/${form.dataset.id}/status`,{method:'POST',body:{status:'shipped',...data}}),true);
  if(form.id==='refund-form')await afterOrderAction(await api(`/admin/orders/${form.dataset.id}/refund`,{method:'POST'}),true);
  if(['label-form','label-buy-form'].includes(form.id))await afterOrderAction(await api(`/admin/orders/${form.dataset.id}/label`,{method:'POST',body:{action:form.id==='label-form'?'create':'buy',...data}}),true);
  if(form.id==='password-form'){await api('/auth/password',{method:'POST',body:data});state.user=null;state.csrf=null;state.cart={items:[],subtotal:0};location.hash='store';authDialog();await render();toast('Contraseña actualizada. Vuelve a iniciar sesión.');}
}catch(error){toast(error.message,true);}finally{if(btn)btn.disabled=false;}});
window.addEventListener('hashchange',()=>{if(location.hash!=='#catalog')closeDialog();render();});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeDialog();}});
(async()=>{try{state.config=await api('/config');const auth=await api('/auth/me');state.user=auth.user;state.csrf=auth.csrf;await render();}catch(e){$('#app').innerHTML=empty('No se ha podido iniciar la tienda',e.message);}})();
function photoPreview(){return(state.editPhotoIds||[]).map((id,index)=>`<div class="photo-thumb"><img src="/media/${id}.jpg" alt="Foto ${index+1}"><button type="button" data-action="remove-photo" data-index="${index}" aria-label="Eliminar foto ${index+1}">×</button></div>`).join('');}
document.addEventListener('change',async e=>{
  if(e.target.matches('#product-form [name=category]')){$('#product-size').innerHTML=sizeField(e.target.value);return;}
  if(e.target.id!=='product-photos')return;
  const files=[...e.target.files];if(files.length+state.editPhotoIds.length>8){toast('Utiliza un máximo de ocho fotos por producto.',true);e.target.value='';return;}
  const editor=$('#product-form'),ids=state.editPhotoIds;state.uploading=true;const submit=editor.querySelector('button[type="submit"]');submit.disabled=true;
  try{for(const file of files){if(file.size>5*1024*1024)throw new Error('Cada foto debe tener un máximo de 5 MB.');const prepared=await preparePhoto(file);const r=await fetch('/api/admin/media',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'image/jpeg','X-CSRF-Token':state.csrf},body:prepared});const result=await r.json();if(!r.ok)throw new Error(result.error);if(!editor.isConnected)return;ids.push(result.id);$('#photo-preview').innerHTML=photoPreview();}toast('Fotos subidas. Guarda el producto para aplicar los cambios.');}catch(error){toast(error.message,true);}finally{if(editor.isConnected){state.uploading=false;submit.disabled=false;}e.target.value='';}
});
function forgotDialog(){dialog('Recuperar contraseña',`<p>Introduce el correo electrónico de tu cuenta para recibir un enlace de recuperación.</p><form id="forgot-form">${field('email','Correo electrónico','','email','required autocomplete="email"')}<div class="form-actions"><button class="btn primary" type="submit">Enviar enlace de recuperación</button></div></form>`);}
function couponsPage(rows){return adminShell('coupons',`${title('Cupones de descuento','Vigencia, límites y descuentos calculados en el servidor.','<button class="btn primary" data-action="new-coupon">+ Nuevo cupón</button>')}<div class="note">El descuento solo se aplica a los productos. Los usos se reservan al finalizar la compra y se confirman tras el pago. La cancelación y el vencimiento liberan la reserva.</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Código</th><th>Descuento</th><th>Vigencia</th><th>Usos / reservas</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${escape(c.code)}</strong><small>${c.active?'Activo':'Inactivo'}</small></td><td>${c.type==='percent'?`${c.value/100}%`:money(c.value)}<small>Mínimo ${money(c.min_subtotal)}</small></td><td>${date(c.starts_at)}<small>Hasta ${date(c.ends_at)}</small></td><td>${c.used||0} / ${c.reserved||0}<small>Límite total: ${c.max_uses} · Por cliente: ${c.per_user_limit}</small></td><td><button class="btn small" data-action="toggle-coupon" data-code="${escape(c.code)}" data-active="${!c.active}">${c.active?'Desactivar':'Activar'}</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('Crea tu primer cupón'):''}</section>`);}
function couponDialog(){const local=v=>new Date(v.getTime()-v.getTimezoneOffset()*60000).toISOString().slice(0,16);dialog('Nuevo cupón',`<form id="coupon-form"><div class="form-grid">${field('code','Código','','text','required minlength="3" maxlength="40" pattern="[A-Za-z0-9_-]+"')}<label class="field">Tipo<select name="type"><option value="percent">Porcentaje (%)</option><option value="fixed">Importe fijo (${currencyLabel()})</option></select></label>${field('value',`Descuento (% o ${currencyLabel()})`,'','number','required min="0.01" step="0.01"')}${field('min_subtotal',`Subtotal mínimo (${currencyLabel()})`,'0','number','required min="0" step="0.01"')}${field('max_discount',`Descuento máximo (${currencyLabel()}, opcional)`,'','number','min="0.01" step="0.01"')}${field('max_uses','Límite total de usos','100','number','required min="1"')}${field('per_user_limit','Límite por cliente','1','number','required min="1"')}${field('starts_at','Inicio',local(new Date()),'datetime-local','required')}${field('ends_at','Fin',local(new Date(Date.now()+30*86400000)),'datetime-local','required')}</div><div class="form-actions"><button class="btn primary" type="submit">Crear cupón</button></div></form>`);}
const invoiceEnvironments={demo:'Simulación',homologation:'Homologación',production:'Producción'};
const invoiceStatus={authorized:'Autorizada',processing:'En proceso',submitting:'Enviando',unknown:'Consultar proveedor',not_found:'No encontrada',rejected:'Rechazada',cancelled:'Cancelada'};
function invoiceSummary(row){if(!row)return'';return`<div class="note"><strong>NF-e ${escape(row.number||'')} · ${invoiceStatus[row.status]||row.status}</strong><p>${row.environment==='demo'?'SIMULACIÓN · sin validez fiscal':row.environment==='homologation'?'HOMOLOGACIÓN · sin validez fiscal':'Producción'}</p>${row.pdf_url?`<a class="btn small" href="/api/orders/${row.order_id}/invoice/pdf" target="_blank" rel="noopener">DANFE ↓</a>`:''} ${row.xml_url?`<a class="btn small" href="/api/orders/${row.order_id}/invoice/xml" target="_blank" rel="noopener">XML ↓</a>`:''}</div>`;}
function invoicesPage(rows){return adminShell('invoices',`${title('Facturas','Emisión, autorización, documentos y cancelación vinculados al pedido.')}<div class="note">Entorno fiscal: ${state.config.fiscal_environment==='production'?'Producción':state.config.fiscal_environment==='demo'?'Simulación sin validez fiscal':'Homologación sin validez fiscal'}. Para emitir, abre un pedido pagado antes del envío.</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Factura / serie</th><th>Estado</th><th>Entorno</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>#${r.order_number}</td><td>${escape(r.customer_name)}</td><td>${escape(r.number||'—')} / ${escape(r.series||'—')}</td><td>${invoiceStatus[r.status]||r.status}</td><td>${escape(invoiceEnvironments[r.environment]||r.environment)}</td><td><button class="btn small" data-action="invoice" data-id="${r.order_id}">Gestionar</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('No se ha emitido ninguna factura'):''}</section>`);}
function invoiceDialog(order,row){state.invoiceOrder=order;dialog(`NF-e · Pedido #${order.number}`,`${row?invoiceSummary(row)+`<p class="muted">${escape(row.message||'')}</p><p class="form-help">Referencia: ${escape(row.ref)}</p>`:'<p>La emisión utilizará los artículos, el descuento y el envío registrados en este pedido.</p>'}<div class="form-actions">${!row||['rejected','not_found'].includes(row.status)?`<button class="btn primary" data-action="invoice-issue" data-id="${order.id}">Revisar y emitir NF-e</button>`:''}${row?`<button class="btn" data-action="invoice-consult" data-id="${order.id}">Consultar estado</button>`:''}${row?.status==='authorized'?`<button class="btn danger" data-action="invoice-cancel" data-id="${order.id}">Cancelar NF-e</button>`:''}</div>`);}
function invoiceIssueDialog(id,preview){dialog('Revisar emisión de NF-e',`<p>${state.config.fiscal_environment==='demo'?'Esta operación es una simulación, sin validez fiscal.':state.config.fiscal_environment==='homologation'?'Emisión en homologación, sin validez fiscal.':'Esta operación enviará una NF-e de producción para su autorización.'}</p>${preview.error?`<p class="danger-note">${escape(preview.error)}</p>`:''}<form id="invoice-emit-form" data-id="${id}">${preview.items.map((item,index)=>`<fieldset class="fiscal-item"><legend>${escape(item.name)}</legend><div class="form-grid">${fiscalEditor(item.fiscal,`item_${index}_`)}</div></fieldset>`).join('')}<input type="hidden" name="item_count" value="${preview.items.length}">${field('payment_type','Código fiscal del método de pago',preview.payment?.forma_pagamento||'','text',state.config.fiscal_environment==='demo'?'maxlength="2"':'required pattern="[0-9]{2}" maxlength="2"')}<p class="form-help">Comprueba el método de pago recibido (p. ej., 03 crédito, 04 débito, 15 boleto, 17 PIX dinámico, 18 monedero digital).</p><label class="field">Datos complementarios del pago (avanzado)<textarea name="payment_extra" class="code-field">${escape(JSON.stringify(Object.fromEntries(Object.entries(preview.payment||{}).filter(([k])=>!['forma_pagamento','valor_pagamento'].includes(k))),null,2))}</textarea></label><p class="form-help">Revisa el NCM, CFOP y los impuestos con el asesor contable. Las cantidades, precios, descuento y envío proceden del pedido.</p>${preview.payload&&!preview.payload.demo?`<details><summary>Consultar los datos completos de la factura</summary><pre>${escape(JSON.stringify(preview.payload,null,2))}</pre></details>`:''}<div class="form-actions"><button class="btn primary" type="submit">Confirmar emisión</button></div></form>`);}
function emailsPage(rows){return adminShell('emails',`${title('Correos de recuperación','Consulta la cola y los intentos de envío.')}<div class="note">${state.config.mode==='demo'?'En la demostración, los mensajes aparecen aquí y no se envían.':'Los mensajes se procesan cada minuto, con un máximo de cinco intentos. El contenido y los enlaces no se muestran en producción.'}</div><section class="panel">${rows.length?rows.map(r=>`<article class="email-row"><strong>${escape(r.subject)}</strong><p class="muted">${escape(r.recipient)} · ${r.sent_at?'Enviado':r.attempts>=5?'Error definitivo':'En cola'} · Intentos: ${r.attempts}</p>${r.last_error?`<p class="danger-note">${escape(r.last_error)}</p>`:''}${r.preview?`<pre>${escape(r.preview)}</pre>`:''}</article>`).join(''):empty('No hay correos en cola')}</section>`);}
const fiscalInputs=[['codigo_ncm','NCM (8 dígitos)'],['cfop','CFOP (4 dígitos)'],['unidade_comercial','Unidad comercial'],['icms_origem','Origen de la mercancía'],['icms_situacao_tributaria','Situación tributaria ICMS / CSOSN'],['pis_situacao_tributaria','Situación tributaria PIS'],['cofins_situacao_tributaria','Situación tributaria COFINS']];
function fiscalEditor(f,prefix=''){const extras=Object.fromEntries(Object.entries(f).filter(([k])=>!fiscalInputs.some(([key])=>key===k)));return`<div class="field full"><strong>Datos fiscales</strong><span class="muted">Configura los datos siguiendo las indicaciones del asesor contable.</span></div>${fiscalInputs.map(([key,label])=>field(prefix+key,label,f[key]??'','text',key==='codigo_ncm'?'maxlength="8"':key==='cfop'?'maxlength="4"':'')).join('')}<label class="field full">Campos tributarios adicionales (avanzado)<textarea name="${prefix}fiscal_extra" class="code-field">${escape(JSON.stringify(extras,null,2))}</textarea></label>`;}
function readFiscal(data,prefix=''){const value=JSON.parse(data[prefix+'fiscal_extra']||'{}');for(const [key] of fiscalInputs){const input=data[prefix+key];if(input?.trim())value[key]=input.trim();else delete value[key];}return value;}

async function preparePhoto(file){
  const bitmap=await createImageBitmap(file);
  try{const scale=Math.min(1,1280/bitmap.width,1280/bitmap.height),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const context=canvas.getContext("2d");context.fillStyle="#ffffff";context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);return await new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error("Imagen no válida.")),"image/jpeg",0.85));}finally{bitmap.close();}
}
